// Turno que estourou o tempo sem resposta (PROD, 2026-11-15: a mensagem de um cliente ficou 2h25 parada): o cliente recebe o texto
// de contingencia e, quando escrever de novo, a mensagem antiga e reprocessada junto. TESTE: so envia para teste.contatos_escrita.
const cfg = { wid: '{{BV:chatmaster.whatsapp_id}}', fila: '{{BV:chatmaster.queue_id}}' };
const contingencia = "{{BV:textos.contingencia}}"; // o encerramento da fila humana nao passa mais por aqui (25/11): o agente retoma a conversa (Decidir retorno)
return $input.all().map((x) => x.json).filter((l) => l.contato_id != null).map((l, k) => ({ json: { contato_id: l.contato_id, texto: contingencia,
  req: bvMTexto({ texto: contingencia }, l.telefone, cfg), simulado: bvSimulado(l.telefone) }, pairedItem: k }));

const p = $('Montar aviso').item.json;
const st = p.simulado ? 200 : Number($input.item.json.statusCode || 0); // 0 = sem resposta
const ok = st >= 200 && st < 300;
// a tentativa ja saiu de tentativas_recepcao: falha nao repete, so fica registrada
return { json: { contato_id: p.contato_id, texto: ok ? p.texto : null, code: ok ? null : (st ? `HTTP_${st}` : 'SEM_RESPOSTA'), status: st } };

{{BV:INCLUDE:shared/mensagens.js}}
// Encerramento da fila humana com o cliente por ultimo (owner, 2026-11-25): o texto fixo "a equipe nao conseguiu te responder" saiu.
// Se a equipe respondeu e o cliente so agradeceu, se despediu ou confirmou, encerra calado; senao o agente retoma a conversa pelas
// mensagens que ficaram sem resposta (Montar retorno -> Chamar retorno). So contato e telefone seguem adiante.
return $input.all().map((x, k) => ({ l: x.json, k })).filter((x) => x.l && x.l.contato_id != null && bvMRetomaFila(x.l))
  .map((x) => ({ json: { contato_id: x.l.contato_id, telefone: x.l.telefone }, pairedItem: x.k }));
